// Stable entry point for Firestore usage tracking (required by main.js).
//
// Production builds use a pre-bundled, tree-shaken copy of the Firebase SDK
// (`firestore.bundle.cjs`, generated by `npm run build:firestore` via
// esbuild — 170KB instead of the full ~121MB firebase/@firebase tree).
// If the bundle is missing (e.g. fresh checkout without `npm install`),
// fall back to the raw SDK source so `electron-forge start` still works.
let Firestore;
try {
  ({Firestore} = require('./firestore.bundle.cjs'));
} catch (_e) {
  ({Firestore} = require('./firestore.sdk.js'));
}

module.exports = {
  Firestore,
};
